"""Load data generated by molecular dynamics simulations"""
import os
import re
import numpy as np
from .._registry import F
from .._struct import Struct
from ..config import config


def _fileparts(p):
    """MATLAB fileparts (both separators on Windows)."""
    k = max(p.rfind('/'), p.rfind('\\') if os.sep == '\\' else -1)
    path, name = (p[:k], p[k + 1:]) if k >= 0 else ('', p)
    j = name.rfind('.')
    return (path, name[:j], name[j:]) if j >= 0 else (path, name, '')


def _fullfile(path, fname):
    """MATLAB fullfile(path, fname): joined with filesep; on Windows '/' becomes '\\'."""
    s = (path + os.sep + fname) if path else fname
    return s.replace('/', os.sep) if os.sep == '\\' else s


def _normalize(v):
    return v / np.sqrt(np.sum(v * v, axis=1, keepdims=True))


def _dihedral(a1T, a2T, a3T, a4T):
    a1 = _normalize(a1T - a2T)
    a2 = _normalize(a3T - a2T)
    a3 = _normalize(a3T - a4T)
    b1 = np.cross(a2, a3, axis=1)
    b2 = np.cross(a1, a2, axis=1)
    vec1 = np.sum(a1 * b1, axis=1) * np.sqrt(np.sum(a2 * a2, axis=1))
    vec2 = np.sum(b1 * b2, axis=1)
    return np.arctan2(vec1, vec2)


def _orientproteintraj(traj):
    nAtoms = traj.shape[2]
    mass = 1
    traj = traj - np.mean(traj, axis=2, keepdims=True)
    firstStep = traj[0, :, :]
    x, y, z = firstStep[0, :], firstStep[1, :], firstStep[2, :]
    I = np.zeros((3, 3))
    I[0, 0] = np.sum(mass * (y ** 2 + z ** 2))
    I[1, 1] = np.sum(mass * (x ** 2 + z ** 2))
    I[2, 2] = np.sum(mass * (x ** 2 + y ** 2))
    I[0, 1] = -np.sum(mass * (x * y))
    I[1, 0] = I[0, 1]
    I[0, 2] = -np.sum(mass * (x * z))
    I[2, 0] = I[0, 2]
    I[1, 2] = -np.sum(mass * (y * z))
    I[2, 1] = I[1, 2]
    I = I / np.linalg.norm(I, 2)
    _, _, Vh = np.linalg.svd(I)
    a = Vh.T
    principal_axes = a[:, ::-1].copy()
    if np.linalg.det(principal_axes) < 0:
        principal_axes[:, 0] = -principal_axes[:, 0]
    RAlign = principal_axes
    for k in range(nAtoms):
        traj[:, :, k] = traj[:, :, k] @ RAlign
    return traj


def _calcbestq(rOld, rNew, mass):
    nAtoms = rOld.shape[1]
    if rOld.shape[0] != 3 or rNew.shape[0] != 3 or nAtoms != rNew.shape[1]:
        raise ValueError('rOld and rNew both must have size (3,nAtoms).')
    mass = np.asarray(mass, dtype=float)
    if mass.ndim != 2 or mass.shape[0] != 1 or mass.shape[1] != nAtoms:
        raise ValueError('mass must be a row vector with length equal to nAtoms.')
    weights = mass / np.sum(mass)
    left = rOld * np.sqrt(weights)
    right = rNew * np.sqrt(weights)
    M = left @ right.T
    Sxx, Syx, Szx, Sxy, Syy, Szy, Sxz, Syz, Szz = M.ravel(order='F')
    N = np.array([[(Sxx + Syy + Szz), (Syz - Szy), (Szx - Sxz), (Sxy - Syx)],
                  [(Syz - Szy), (Sxx - Syy - Szz), (Sxy + Syx), (Szx + Sxz)],
                  [(Szx - Sxz), (Sxy + Syx), (-Sxx + Syy - Szz), (Syz + Szy)],
                  [(Sxy - Syx), (Szx + Sxz), (Syz + Szy), (-Sxx - Syy + Szz)]])
    D, V = np.linalg.eigh(N)                      # N is symmetric: MATLAB eig uses the symmetric solver
    emax = int(np.argmax(np.real(D)))
    q = np.real(V[:, emax])
    ii = int(np.argmax(np.abs(q)))
    return (q * np.sign(q[ii])).reshape(4, 1)


def _processMDfiles(TrajFile, TopFile, SegName, ResName, LabelName, AtomNames, ExtCombo):
    if ExtCombo == '.DCD,.PSF':
        structure = F.md_readpsf(TopFile, SegName, ResName, LabelName, AtomNames)
        Traj = Struct(F.md_readdcd(TrajFile, structure.idx_ProteinLabel))
    elif ExtCombo == '.TRR,.GRO':
        structure = F.md_readgro(TopFile, ResName, LabelName, AtomNames)
        Traj = Struct(F.md_readtrr(TrajFile))
    else:
        raise ValueError(f'Trajectory and structure file type combination {ExtCombo} is either '
                         'not supported or not properly entered.')
    xyz = np.asarray(Traj.xyz)
    xyz = xyz.reshape(xyz.shape + (1,) * (3 - xyz.ndim)) if xyz.ndim < 3 else xyz
    Traj.ProtCAxyz = xyz[:, :, np.ravel(np.asarray(structure.idx_ProteinCA, dtype=bool), order='F')]
    Traj.Labelxyz = xyz[:, :, np.ravel(np.asarray(structure.idx_SpinLabel, dtype=bool), order='F')]
    del Traj['xyz']
    return Traj, structure


def mdload(TrajFile=None, TopFile=None, Info=None, Opt=None):
    """mdload(TrajFile, TopFile, Info=None, Opt=None) -> MD struct: nSteps, [ProtCAxyz (3 x nCA x nSteps,
    with Opt.keepProtCA)], dt, FrameTraj (3x3x1xnSteps), dihedrals (nDihedrals x 1 x nSteps),
    RProtDiff (3x3xnSteps), FrameTrajwrtProt (3x3x1xnSteps). Formats: .DCD + .PSF, .TRR + .GRO;
    labels R1 and TOAC. No progress printing."""
    if TrajFile is None:
        return None
    if TopFile is None:
        raise ValueError('At least two input arguments (trajecory file and structure file) are needed.')
    Info = Struct(Info) if isinstance(Info, dict) else Struct()
    Opt = Struct(Opt) if isinstance(Opt, dict) else Struct()
    if 'Verbosity' not in Opt:
        Opt.Verbosity = 1
    if 'keepProtCA' not in Opt:
        Opt.keepProtCA = False
    config.LogLevel = Opt.Verbosity
    if 'ResName' not in Info:
        Info.ResName = 'CYR1'
    ResName = Info.ResName
    if 'LabelName' not in Info:
        if ResName == 'TOC':
            Info.LabelName = 'TOAC'
        elif ResName == 'CYR1':
            Info.LabelName = 'R1'
        else:
            raise ValueError('Info.LabelName is missing and cannot be inferred from Info.LabelName.')
    LabelName = Info.LabelName
    if LabelName not in ('R1', 'TOAC'):
        raise ValueError(f"Label '{LabelName}' (given in Info.LabelName) is not supported.")
    if 'AtomNames' not in Info:
        if LabelName == 'R1':
            F.logmsg(1, 'Using default atom names for label R1.')
            Info.AtomNames = Struct(ONname='ON', NNname='NN', C1name='C1', C2name='C2', C1Rname='C1R',
                                    C2Rname='C2R', C1Lname='C1L', S1Lname='S1L', SGname='SG', CBname='CB',
                                    CAname='CA', Nname='N')
        else:
            F.logmsg(1, 'Using default atom names for label TOAC.')
            Info.AtomNames = Struct(ONname='OE', NNname='ND', CGSname='CG2', CGRname='CG1', CBSname='CB2',
                                    CBRname='CB1', CAname='CA', Nname='N')
    AtomNames = Info.AtomNames
    if 'SegName' not in Info:
        Info.SegName = ''
    SegName = Info.SegName
    if not isinstance(TopFile, str) or not re.search(r'\w+\.\w+', TopFile):
        raise ValueError('TopFile must be given as a character array, including the filename extension.')
    if os.path.exists(TopFile):
        p, n, e = _fileparts(TopFile)
        TopFileExt = e
        TopFile = _fullfile(p, n + e)
    else:
        raise ValueError(f'TopFile "{TopFile}" could not be found.')
    if isinstance(TrajFile, str):
        TrajFile = [TrajFile]
    if not isinstance(TrajFile, (list, tuple)):
        raise ValueError("Please provide 'TrajFile' as a single character array (single trajectory file) or a cell "
                         "array whose elements are character arrays (multiple trajectory files).")
    if not all(isinstance(t, str) for t in TrajFile):
        raise ValueError('TrajFile must be a cell array of character arrays.')
    TrajFile = list(TrajFile)
    nTrajFiles = len(TrajFile)
    paths, exts = [], []
    for k in range(nTrajFiles):
        if not os.path.exists(TrajFile[k]):
            raise ValueError(f'TrajFile "{TrajFile[k]}" could not be found.')
        p, n, e = _fileparts(TrajFile[k])
        paths.append(p)
        exts.append(e)
        TrajFile[k] = _fullfile(p, n + e)
    if not all(e == exts[0] for e in exts):
        raise ValueError('At least two of the TrajFile file extensions are not identical.')
    if not all(p == paths[0] for p in paths):
        raise ValueError('At least two of the TrajFilePath locations are not identical.')
    TrajFileExt = exts[0].upper()
    TopFileExt = TopFileExt.upper()
    if TrajFileExt not in ('.DCD', '.TRR'):
        raise ValueError(f'The trajectory file extension "{TrajFileExt}" is not supported.')
    if TopFileExt not in ('.PSF', '.GRO'):
        raise ValueError(f'The topology file extension "{TopFileExt}" is not supported.')
    F.logmsg(1, '-- extracting data from MD trajectory files -----------------------------------------')
    MD = Struct()
    MD.nSteps = 0.0
    MD.ProtCAxyz = None
    MD.Labelxyz = None
    MD.dt = None
    ExtCombo = TrajFileExt + ',' + TopFileExt
    psf = None
    for iTrajFile in range(nTrajFiles):
        F.logmsg(1, 'trajectory %d', iTrajFile + 1)
        Traj_, psf = _processMDfiles(TrajFile[iTrajFile], TopFile, SegName, ResName, LabelName, AtomNames, ExtCombo)
        if MD.dt is not None and MD.dt != Traj_.dt:
            raise ValueError(f'Time steps of trajectory files {TrajFile[iTrajFile]} and {TrajFile[iTrajFile - 1]} are not equal.')
        MD.dt = Traj_.dt
        MD.ProtCAxyz = Traj_.ProtCAxyz if MD.ProtCAxyz is None else np.concatenate([MD.ProtCAxyz, Traj_.ProtCAxyz], axis=0)
        MD.Labelxyz = Traj_.Labelxyz if MD.Labelxyz is None else np.concatenate([MD.Labelxyz, Traj_.Labelxyz], axis=0)
        MD.nSteps = MD.nSteps + Traj_.nFrames
    nSteps = int(MD.nSteps)
    keys = ('ON', 'NN', 'C1', 'C2', 'C1R', 'C2R', 'C1L', 'S1L', 'SG', 'CB', 'CA', 'N') if LabelName == 'R1' \
        else ('ON', 'NN', 'CGS', 'CGR', 'CBS', 'CBR', 'CA', 'N')
    v = {}
    for key in keys:
        m = np.ravel(np.asarray(psf['idx_' + key], dtype=bool), order='F')
        sel = MD.Labelxyz[:, :, m]
        v[key] = sel.reshape(sel.shape[0], 3) if sel.shape[2] == 1 else sel
    del MD['Labelxyz']
    F.logmsg(1, 'Calculating label frames...')
    FrameTraj = np.zeros((nSteps, 3, 3))
    if LabelName == 'R1':
        NNNO = _normalize(v['ON'] - v['NN'])
        NNC1 = _normalize(v['C1'] - v['NN'])
        NNC2 = _normalize(v['C2'] - v['NN'])
        FrameTraj[:, :, 2] = _normalize(np.cross(NNC1, NNNO, axis=1) + np.cross(NNNO, NNC2, axis=1))
    else:
        NNNO = _normalize(v['ON'] - v['NN'])
        NNCGR = _normalize(v['CGR'] - v['NN'])
        NNCGS = _normalize(v['CGS'] - v['NN'])
        FrameTraj[:, :, 2] = _normalize(np.cross(NNCGR, NNNO, axis=1) + np.cross(NNNO, NNCGS, axis=1))
    FrameTraj[:, :, 0] = NNNO
    FrameTraj[:, :, 1] = np.cross(FrameTraj[:, :, 2], FrameTraj[:, :, 0], axis=1)
    F.logmsg(1, 'Calculating side chain dihedral angles...')
    if LabelName == 'R1':
        dihedrals = np.zeros((nSteps, 5))
        dihedrals[:, 0] = _dihedral(v['N'], v['CA'], v['CB'], v['SG'])
        dihedrals[:, 1] = _dihedral(v['CA'], v['CB'], v['SG'], v['S1L'])
        dihedrals[:, 2] = _dihedral(v['CB'], v['SG'], v['S1L'], v['C1L'])
        dihedrals[:, 3] = _dihedral(v['SG'], v['S1L'], v['C1L'], v['C1R'])
        dihedrals[:, 4] = _dihedral(v['S1L'], v['C1L'], v['C1R'], v['C2R'])
    else:
        dihedrals = np.zeros((nSteps, 2))
        dihedrals[:, 0] = _dihedral(v['CA'], v['CBS'], v['CGS'], v['NN'])
        dihedrals[:, 1] = _dihedral(v['CA'], v['CBR'], v['CGR'], v['NN'])
    MD.FrameTraj = np.transpose(FrameTraj.reshape(nSteps, 3, 3, 1), (1, 2, 3, 0))
    MD.dihedrals = np.transpose(dihedrals.reshape(nSteps, -1, 1), (1, 2, 0))
    F.logmsg(1, '-- removing protein global diffusion -----------------------------------------')
    P = _orientproteintraj(np.asarray(MD.ProtCAxyz, dtype=float))
    P = np.ascontiguousarray(np.transpose(P, (1, 2, 0)))
    MD.RProtDiff = np.zeros((3, 3, nSteps))
    MD.RProtDiff[:, :, 0] = np.eye(3)
    qTraj = np.zeros((4, nSteps))
    qTraj[:, 0] = [1, 0, 0, 0]
    nAtoms = P.shape[1]
    mass = np.ones((1, nAtoms))
    FTw = np.zeros((3, 3, 1, nSteps))
    FTw[:, :, :, 0] = MD.FrameTraj[:, :, :, 0]
    refFrame = P[:, :, 0].copy()
    for iStep in range(1, nSteps):
        thisFrame = P[:, :, iStep].copy()
        q = _calcbestq(refFrame, thisFrame, mass)
        R = F.quat2rotmat(q)
        P[:, :, iStep] = R.T @ thisFrame
        FTw[:, :, 0, iStep] = R.T @ MD.FrameTraj[:, :, 0, iStep]
        MD.RProtDiff[:, :, iStep] = R @ MD.RProtDiff[:, :, iStep - 1]
        qTraj[:, iStep] = np.ravel(F.quatmult(q, qTraj[:, iStep - 1:iStep]))
    MD.ProtCAxyz = P
    MD.FrameTrajwrtProt = FTw
    if not Opt.keepProtCA:
        del MD['ProtCAxyz']
    if Opt.Verbosity:
        F.logmsg(1, 'Summary:')
        F.logmsg(1, '  Label: %s', LabelName)
        F.logmsg(1, '  Number of trajectories: %d', nTrajFiles)
        F.logmsg(1, '  Number of time steps: %d', MD.nSteps)
        F.logmsg(1, '  Size of time step: %g ps', MD.dt / 1e-12)
    return MD
